-- 1. EXTENSIONS & PREREQUISITES
CREATE EXTENSION IF NOT EXISTS "uuid-ossp";
CREATE EXTENSION IF NOT EXISTS "pgcrypto";

-- 2. CUSTOM ENUM TYPES
DO $$ BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_type WHERE typname = 'user_role') THEN
        CREATE TYPE "user_role" AS ENUM ('ADMIN', 'CUSTOMER', 'STAFF', 'MANAGER');
    END IF;
END $$;

DO $$ BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_type WHERE typname = 'order_status') THEN
        CREATE TYPE "order_status" AS ENUM ('PENDING', 'CONFIRMED', 'PROCESSING', 'SHIPPED', 'DELIVERED', 'CANCELLED');
    END IF;
END $$;

DO $$ BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_type WHERE typname = 'payment_status') THEN
        CREATE TYPE "payment_status" AS ENUM ('UNPAID', 'AUTHORIZED', 'PAID', 'FAILED', 'REFUNDED');
    END IF;
END $$;

-- 3. AUDIT TRIGGER FUNCTION FOR updated_at
CREATE OR REPLACE FUNCTION trigger_set_timestamp()
RETURNS TRIGGER AS $$
BEGIN
    NEW.updated_at = CURRENT_TIMESTAMP;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

-- 4. TABLE DEFINITIONS (Topologically Sorted for Referential Integrity)

-- Table: users (Core user accounts and authentication credentials)
CREATE TABLE IF NOT EXISTS "users" (
    "id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    "created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted_at" TIMESTAMPTZ,
    "version" INTEGER NOT NULL DEFAULT 1,
    "email" VARCHAR(255) NOT NULL UNIQUE,
    "password_hash" VARCHAR(255) NOT NULL,
    "full_name" VARCHAR(150) NOT NULL,
    "phone_number" VARCHAR(30),
    "role" VARCHAR(50) NOT NULL DEFAULT 'CUSTOMER' CHECK (role IN ('ADMIN', 'CUSTOMER', 'STAFF', 'MANAGER')),
    "is_active" BOOLEAN NOT NULL DEFAULT TRUE,
    CONSTRAINT "chk_users_email_format" CHECK (email ~* '^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}$')
);
COMMENT ON TABLE "users" IS 'Core user accounts and authentication credentials';
COMMENT ON COLUMN "users"."id" IS 'Unique surrogate primary key (UUIDv4/v7)';
COMMENT ON COLUMN "users"."created_at" IS 'Timestamp when record was created';
COMMENT ON COLUMN "users"."updated_at" IS 'Timestamp when record was last updated';
COMMENT ON COLUMN "users"."deleted_at" IS 'Soft-delete timestamp; NULL indicates active record';
COMMENT ON COLUMN "users"."version" IS 'Optimistic locking version counter';
COMMENT ON COLUMN "users"."email" IS 'User primary email address';
COMMENT ON COLUMN "users"."password_hash" IS 'Argon2/Bcrypt hashed password';
COMMENT ON COLUMN "users"."full_name" IS 'Full display name';
COMMENT ON COLUMN "users"."phone_number" IS 'E.164 formatted contact phone number';
COMMENT ON COLUMN "users"."role" IS 'Security RBAC role';
COMMENT ON COLUMN "users"."is_active" IS 'Account active status flag';
DROP TRIGGER IF EXISTS "trg_users_updated_at" ON "users";
CREATE TRIGGER "trg_users_updated_at"
BEFORE UPDATE ON "users"
FOR EACH ROW EXECUTE FUNCTION trigger_set_timestamp();

-- Table: categories (Hierarchical item/service classification taxonomy)
CREATE TABLE IF NOT EXISTS "categories" (
    "id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    "created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted_at" TIMESTAMPTZ,
    "version" INTEGER NOT NULL DEFAULT 1,
    "parent_id" UUID,
    "name" VARCHAR(100) NOT NULL,
    "slug" VARCHAR(120) NOT NULL UNIQUE,
    "description" TEXT,
    CONSTRAINT "fk_categories_parent" FOREIGN KEY ("parent_id") REFERENCES "categories" ("id") ON DELETE SET NULL ON UPDATE CASCADE
);
COMMENT ON TABLE "categories" IS 'Hierarchical item/service classification taxonomy';
COMMENT ON COLUMN "categories"."id" IS 'Unique surrogate primary key (UUIDv4/v7)';
COMMENT ON COLUMN "categories"."created_at" IS 'Timestamp when record was created';
COMMENT ON COLUMN "categories"."updated_at" IS 'Timestamp when record was last updated';
COMMENT ON COLUMN "categories"."deleted_at" IS 'Soft-delete timestamp; NULL indicates active record';
COMMENT ON COLUMN "categories"."version" IS 'Optimistic locking version counter';
COMMENT ON COLUMN "categories"."parent_id" IS 'Self-referencing parent category for nesting';
COMMENT ON COLUMN "categories"."name" IS 'Category display name';
COMMENT ON COLUMN "categories"."slug" IS 'URL-friendly identifier slug';
COMMENT ON COLUMN "categories"."description" IS 'Category description';
DROP TRIGGER IF EXISTS "trg_categories_updated_at" ON "categories";
CREATE TRIGGER "trg_categories_updated_at"
BEFORE UPDATE ON "categories"
FOR EACH ROW EXECUTE FUNCTION trigger_set_timestamp();

-- Table: orders (Customer order headers tracking checkout transactions and lifecycle)
CREATE TABLE IF NOT EXISTS "orders" (
    "id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    "created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted_at" TIMESTAMPTZ,
    "version" INTEGER NOT NULL DEFAULT 1,
    "order_number" VARCHAR(50) NOT NULL UNIQUE,
    "user_id" UUID NOT NULL,
    "status" VARCHAR(30) NOT NULL DEFAULT 'PENDING' CHECK (status IN ('PENDING', 'CONFIRMED', 'PROCESSING', 'SHIPPED', 'DELIVERED', 'CANCELLED')),
    "total_amount" NUMERIC(14, 2) NOT NULL CHECK (total_amount >= 0),
    "shipping_address" TEXT NOT NULL,
    "notes" TEXT,
    CONSTRAINT "fk_orders_user_id" FOREIGN KEY ("user_id") REFERENCES "users" ("id") ON DELETE RESTRICT ON UPDATE CASCADE
);
COMMENT ON TABLE "orders" IS 'Customer order headers tracking checkout transactions and lifecycle';
COMMENT ON COLUMN "orders"."id" IS 'Unique surrogate primary key (UUIDv4/v7)';
COMMENT ON COLUMN "orders"."created_at" IS 'Timestamp when record was created';
COMMENT ON COLUMN "orders"."updated_at" IS 'Timestamp when record was last updated';
COMMENT ON COLUMN "orders"."deleted_at" IS 'Soft-delete timestamp; NULL indicates active record';
COMMENT ON COLUMN "orders"."version" IS 'Optimistic locking version counter';
COMMENT ON COLUMN "orders"."order_number" IS 'Human-readable unique invoice/order number';
COMMENT ON COLUMN "orders"."user_id" IS 'Foreign key to user who placed the order';
COMMENT ON COLUMN "orders"."status" IS 'Current order state';
COMMENT ON COLUMN "orders"."total_amount" IS 'Final calculated total payable amount';
COMMENT ON COLUMN "orders"."shipping_address" IS 'Physical shipping destination details';
COMMENT ON COLUMN "orders"."notes" IS 'Customer or fulfillment instructions';
DROP TRIGGER IF EXISTS "trg_orders_updated_at" ON "orders";
CREATE TRIGGER "trg_orders_updated_at"
BEFORE UPDATE ON "orders"
FOR EACH ROW EXECUTE FUNCTION trigger_set_timestamp();

-- Table: audit_logs (Immutable historical log of critical domain events and data alterations)
CREATE TABLE IF NOT EXISTS "audit_logs" (
    "id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    "created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "user_id" UUID,
    "action" VARCHAR(100) NOT NULL,
    "entity_name" VARCHAR(100) NOT NULL,
    "entity_id" VARCHAR(100) NOT NULL,
    "changes" JSONB,
    "ip_address" VARCHAR(45),
    CONSTRAINT "fk_audit_logs_user_id" FOREIGN KEY ("user_id") REFERENCES "users" ("id") ON DELETE SET NULL ON UPDATE CASCADE
);
COMMENT ON TABLE "audit_logs" IS 'Immutable historical log of critical domain events and data alterations';
COMMENT ON COLUMN "audit_logs"."id" IS 'Surrogate primary key';
COMMENT ON COLUMN "audit_logs"."created_at" IS 'Event occurrence timestamp';
COMMENT ON COLUMN "audit_logs"."user_id" IS 'Actor who triggered the event';
COMMENT ON COLUMN "audit_logs"."action" IS 'Action type: INSERT, UPDATE, DELETE, LOGIN, REFUND';
COMMENT ON COLUMN "audit_logs"."entity_name" IS 'Target entity name';
COMMENT ON COLUMN "audit_logs"."entity_id" IS 'Target entity identifier';
COMMENT ON COLUMN "audit_logs"."changes" IS 'State change diff (old vs new values)';
COMMENT ON COLUMN "audit_logs"."ip_address" IS 'Client IP address';

-- Table: products (Catalog products/items offered for order or service)
CREATE TABLE IF NOT EXISTS "products" (
    "id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    "created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted_at" TIMESTAMPTZ,
    "version" INTEGER NOT NULL DEFAULT 1,
    "category_id" UUID NOT NULL,
    "sku" VARCHAR(64) NOT NULL UNIQUE,
    "name" VARCHAR(200) NOT NULL,
    "description" TEXT,
    "price" NUMERIC(12, 2) NOT NULL CHECK (price >= 0),
    "stock_quantity" INTEGER NOT NULL DEFAULT 0 CHECK (stock_quantity >= 0),
    "metadata" JSONB,
    CONSTRAINT "fk_products_category_id" FOREIGN KEY ("category_id") REFERENCES "categories" ("id") ON DELETE RESTRICT ON UPDATE CASCADE
);
COMMENT ON TABLE "products" IS 'Catalog products/items offered for order or service';
COMMENT ON COLUMN "products"."id" IS 'Unique surrogate primary key (UUIDv4/v7)';
COMMENT ON COLUMN "products"."created_at" IS 'Timestamp when record was created';
COMMENT ON COLUMN "products"."updated_at" IS 'Timestamp when record was last updated';
COMMENT ON COLUMN "products"."deleted_at" IS 'Soft-delete timestamp; NULL indicates active record';
COMMENT ON COLUMN "products"."version" IS 'Optimistic locking version counter';
COMMENT ON COLUMN "products"."category_id" IS 'Foreign key to primary category';
COMMENT ON COLUMN "products"."sku" IS 'Stock Keeping Unit / Unique product code';
COMMENT ON COLUMN "products"."name" IS 'Product title';
COMMENT ON COLUMN "products"."description" IS 'Product detailed specifications';
COMMENT ON COLUMN "products"."price" IS 'Current unit price in default currency';
COMMENT ON COLUMN "products"."stock_quantity" IS 'Available physical inventory quantity';
COMMENT ON COLUMN "products"."metadata" IS 'Extensible dynamic attributes (dimensions, colors, specs)';
DROP TRIGGER IF EXISTS "trg_products_updated_at" ON "products";
CREATE TRIGGER "trg_products_updated_at"
BEFORE UPDATE ON "products"
FOR EACH ROW EXECUTE FUNCTION trigger_set_timestamp();

-- Table: payments (Financial transaction records tied to orders)
CREATE TABLE IF NOT EXISTS "payments" (
    "id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    "created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted_at" TIMESTAMPTZ,
    "version" INTEGER NOT NULL DEFAULT 1,
    "order_id" UUID NOT NULL,
    "payment_reference" VARCHAR(100) NOT NULL UNIQUE,
    "payment_method" VARCHAR(50) NOT NULL,
    "amount" NUMERIC(14, 2) NOT NULL CHECK (amount > 0),
    "status" VARCHAR(30) NOT NULL DEFAULT 'UNPAID' CHECK (status IN ('UNPAID', 'AUTHORIZED', 'PAID', 'FAILED', 'REFUNDED')),
    "gateway_payload" JSONB,
    CONSTRAINT "fk_payments_order_id" FOREIGN KEY ("order_id") REFERENCES "orders" ("id") ON DELETE RESTRICT ON UPDATE CASCADE
);
COMMENT ON TABLE "payments" IS 'Financial transaction records tied to orders';
COMMENT ON COLUMN "payments"."id" IS 'Unique surrogate primary key (UUIDv4/v7)';
COMMENT ON COLUMN "payments"."created_at" IS 'Timestamp when record was created';
COMMENT ON COLUMN "payments"."updated_at" IS 'Timestamp when record was last updated';
COMMENT ON COLUMN "payments"."deleted_at" IS 'Soft-delete timestamp; NULL indicates active record';
COMMENT ON COLUMN "payments"."version" IS 'Optimistic locking version counter';
COMMENT ON COLUMN "payments"."order_id" IS 'Associated order';
COMMENT ON COLUMN "payments"."payment_reference" IS 'External payment gateway transaction reference';
COMMENT ON COLUMN "payments"."payment_method" IS 'Method: CREDIT_CARD, BANK_TRANSFER, VNPAY, MOMO';
COMMENT ON COLUMN "payments"."amount" IS 'Transacted monetary amount';
COMMENT ON COLUMN "payments"."status" IS 'Gateway payment state';
COMMENT ON COLUMN "payments"."gateway_payload" IS 'Raw webhook/callback payload for audit trail';
DROP TRIGGER IF EXISTS "trg_payments_updated_at" ON "payments";
CREATE TRIGGER "trg_payments_updated_at"
BEFORE UPDATE ON "payments"
FOR EACH ROW EXECUTE FUNCTION trigger_set_timestamp();

-- Table: order_items (Individual line items contained within an order)
CREATE TABLE IF NOT EXISTS "order_items" (
    "id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    "created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted_at" TIMESTAMPTZ,
    "version" INTEGER NOT NULL DEFAULT 1,
    "order_id" UUID NOT NULL,
    "product_id" UUID NOT NULL,
    "unit_price" NUMERIC(12, 2) NOT NULL CHECK (unit_price >= 0),
    "quantity" INTEGER NOT NULL CHECK (quantity > 0),
    "subtotal" NUMERIC(14, 2) NOT NULL CHECK (subtotal >= 0),
    CONSTRAINT "fk_order_items_order_id" FOREIGN KEY ("order_id") REFERENCES "orders" ("id") ON DELETE CASCADE ON UPDATE CASCADE,
    CONSTRAINT "fk_order_items_product_id" FOREIGN KEY ("product_id") REFERENCES "products" ("id") ON DELETE RESTRICT ON UPDATE CASCADE
);
COMMENT ON TABLE "order_items" IS 'Individual line items contained within an order';
COMMENT ON COLUMN "order_items"."id" IS 'Unique surrogate primary key (UUIDv4/v7)';
COMMENT ON COLUMN "order_items"."created_at" IS 'Timestamp when record was created';
COMMENT ON COLUMN "order_items"."updated_at" IS 'Timestamp when record was last updated';
COMMENT ON COLUMN "order_items"."deleted_at" IS 'Soft-delete timestamp; NULL indicates active record';
COMMENT ON COLUMN "order_items"."version" IS 'Optimistic locking version counter';
COMMENT ON COLUMN "order_items"."order_id" IS 'Parent order reference';
COMMENT ON COLUMN "order_items"."product_id" IS 'Referenced catalog product';
COMMENT ON COLUMN "order_items"."unit_price" IS 'Historical unit price snapshot at time of purchase';
COMMENT ON COLUMN "order_items"."quantity" IS 'Purchased unit count';
COMMENT ON COLUMN "order_items"."subtotal" IS 'Calculated line item subtotal (quantity * unit_price)';
DROP TRIGGER IF EXISTS "trg_order_items_updated_at" ON "order_items";
CREATE TRIGGER "trg_order_items_updated_at"
BEFORE UPDATE ON "order_items"
FOR EACH ROW EXECUTE FUNCTION trigger_set_timestamp();

-- 5. PERFORMANCE & SEARCH INDEXES

-- Indexes for table: categories
CREATE INDEX IF NOT EXISTS "idx_categories_parent_id" ON "categories" ("parent_id");

-- Indexes for table: orders
CREATE INDEX IF NOT EXISTS "idx_orders_user_id" ON "orders" ("user_id");
CREATE INDEX IF NOT EXISTS "idx_orders_active_status" ON "orders" ("status") WHERE "deleted_at" IS NULL;

-- Indexes for table: audit_logs
CREATE INDEX IF NOT EXISTS "idx_audit_logs_user_id" ON "audit_logs" ("user_id");
CREATE INDEX IF NOT EXISTS "idx_audit_logs_changes_gin" ON "audit_logs" USING gin ("changes");

-- Indexes for table: products
CREATE INDEX IF NOT EXISTS "idx_products_category_id" ON "products" ("category_id");
CREATE INDEX IF NOT EXISTS "idx_products_metadata_gin" ON "products" USING gin ("metadata");

-- Indexes for table: payments
CREATE INDEX IF NOT EXISTS "idx_payments_order_id" ON "payments" ("order_id");
CREATE INDEX IF NOT EXISTS "idx_payments_active_status" ON "payments" ("status") WHERE "deleted_at" IS NULL;
CREATE INDEX IF NOT EXISTS "idx_payments_gateway_payload_gin" ON "payments" USING gin ("gateway_payload");

-- Indexes for table: order_items
CREATE INDEX IF NOT EXISTS "idx_order_items_order_id" ON "order_items" ("order_id");
CREATE INDEX IF NOT EXISTS "idx_order_items_product_id" ON "order_items" ("product_id");
